`timescale 1ns/1ps
`default_nettype none
// AUTO-GENERATED: do not edit this file; edit rtl/lut6_engine.sv.in instead.
// One LUT6 inference engine. Two ping-pong BRAM banks preserve tensor values.
// Input is PRE-ENCODED, 1 bit/clock, CHW flattening as specified in the JSON.
// The 64-bit INIT addresses the LUT with pin0 as bit0 of its truth-table index.
module lut6_sequential #(
    parameter PROGRAM_FILE="rtl/lut6_program.mem",
    parameter TRUTH_FILE="rtl/lut6_truth.mem"
)(
    input  wire clk,
    input  wire rst,
    input  wire input_valid,
    input  wire input_bit,
    output wire input_ready,
    output wire frame_ready,
    input  wire start,
    output wire busy,
    output wire done,
    output wire [2*16-1:0] scores_flat
);
    localparam integer N_INPUT=32;
    localparam integer N_PROGRAM=45;
    localparam integer ADDR_W=6;
    localparam integer PROG_W=100;
    localparam integer N_STAGES=3;
    localparam integer STAGE_W=2;
    localparam integer INDEX_W=5;
    localparam integer PC_W=6;
    localparam integer LOAD_W=5;
    localparam integer BANK0_DEPTH=32;
    localparam integer BANK1_DEPTH=27;
    localparam integer N_CLASSES=2;
    localparam integer CLASS_W=1;
    localparam integer SCORE_W=16;
    localparam integer USE_SPLIT=0;
    localparam integer INIT_ID_W=1;
    localparam integer N_TRUTH=1;
    localparam [ADDR_W-1:0] PAD_ADDR={ADDR_W{1'b1}};
    localparam [STAGE_W-1:0] LAST_STAGE=N_STAGES-1;

    // S_FETCH and S_ROM_WAIT schedule synchronous ROM reads without ambiguity.
    // The optional S_TRUTH_WAIT similarly schedules the compact INIT ROM.
    localparam [3:0] S_LOAD=4'd0, S_READY=4'd1, S_FETCH=4'd2,
                     S_ROM_WAIT=4'd3, S_TRUTH_WAIT=4'd4,
                     S_PIN_ADDR=4'd5, S_MEM_WAIT=4'd6,
                     S_SAMPLE=4'd7, S_EXEC=4'd8, S_DONE=4'd9;
    reg [3:0] state;
    reg [STAGE_W-1:0] stage;
    reg [LOAD_W-1:0] load_index;
    reg [INDEX_W-1:0] local_index;
    reg [PC_W-1:0] pc, program_addr;
    reg [PROG_W-1:0] program_q;
    reg [2:0] pin_index;
    reg [5:0] lut_addr;
    reg [ADDR_W-1:0] read_addr;

    // stage_length is generated from each JSON output_shape, not hardcoded.
    function automatic [INDEX_W-1:0] stage_length(input [STAGE_W-1:0] s);
        begin
            case(s)
            2'd0: stage_length = 5'd27;
            2'd1: stage_length = 5'd8;
            2'd2: stage_length = 5'd10;
                default: stage_length = {INDEX_W{1'b0}};
            endcase
        end
    endfunction

    // Supports nonuniform / noncontiguous output class ranges; no division.
    // Return high bit = valid class, low CLASS_W bits = class index.
    function automatic [CLASS_W:0] class_of_index(input [INDEX_W-1:0] idx);
        begin
            class_of_index={(CLASS_W+1){1'b0}};
            if ((idx >= 5'd0) && (idx < 5'd5)) class_of_index = {1'b1, 1'd0};
            if ((idx >= 5'd5) && (idx < 5'd10)) class_of_index = {1'b1, 1'd1};
        end
    endfunction

    (* rom_style = "block" *) reg [PROG_W-1:0] program_mem[0:N_PROGRAM-1];
    initial $readmemh(PROGRAM_FILE,program_mem);
    always @(posedge clk) begin
        if(state==S_ROM_WAIT)
            program_q <= program_mem[program_addr];
    end

    wire [63:0] truth_word;
    wire [ADDR_W-1:0] operand_addr;
    generate
        if (USE_SPLIT != 0) begin : compact
            (* rom_style="block" *) reg [63:0] truth_mem[0:N_TRUTH-1];
            reg [63:0] truth_q;
            initial $readmemh(TRUTH_FILE,truth_mem);
            always @(posedge clk) begin
                if(state == S_TRUTH_WAIT)
                    truth_q <= truth_mem[program_q[6*ADDR_W +: INIT_ID_W]];
            end
            assign truth_word=truth_q;
            assign operand_addr=program_q[ADDR_W*pin_index +: ADDR_W];
        end else begin : full
            assign truth_word=program_q[63:0];
            assign operand_addr=program_q[64+ADDR_W*pin_index +: ADDR_W];
        end
    endgenerate

    // Ping-pong intermediate memories. No reset on arrays => infer BRAM.
    // Even stages read bank0 and write bank1; odd stages do the reverse.
    (* ram_style="block" *) reg bank0[0:BANK0_DEPTH-1];
    (* ram_style="block" *) reg bank1[0:BANK1_DEPTH-1];
    reg bank0_q,bank1_q;
    wire [INDEX_W-1:0] active_stage_length=stage_length(stage);
    wire [CLASS_W:0] active_class=class_of_index(local_index);
    wire source_bit=stage[0] ? bank1_q : bank0_q;
    wire lut_value=truth_word[lut_addr];

    // A single physical write port is shared by input loading and odd-stage
    // writebacks. This is essential for BRAM inference (not two write ports).
    wire bank0_we=(state==S_LOAD && input_valid) ||
                  (state==S_EXEC && stage[0] && stage!=LAST_STAGE);
    wire [ADDR_W-1:0] bank0_wr_addr=(state==S_LOAD) ? load_index : local_index;
    wire bank0_wr_data=(state==S_LOAD) ? input_bit : lut_value;
    always @(posedge clk) begin
        if(bank0_we)
            bank0[bank0_wr_addr] <= bank0_wr_data;
        if(state==S_MEM_WAIT && !stage[0])
            bank0_q <= bank0[read_addr];
    end
    always @(posedge clk) begin
        if(state==S_EXEC && !stage[0] && stage!=LAST_STAGE)
            bank1[local_index] <= lut_value;
        if(state==S_MEM_WAIT && stage[0])
            bank1_q <= bank1[read_addr];
    end

    reg [SCORE_W-1:0] class_counts[0:N_CLASSES-1];
    genvar g;
    generate for(g=0;g<N_CLASSES;g=g+1) begin: score_map
        assign scores_flat[g*SCORE_W +: SCORE_W]=class_counts[g];
    end endgenerate
    assign input_ready=(state==S_LOAD);
    assign frame_ready=(state==S_READY);
    assign busy=(state>=S_FETCH && state<=S_EXEC);
    assign done=(state==S_DONE);

    integer j;
    always @(posedge clk) begin
        if(rst) begin
            state<=S_LOAD;
            stage<={STAGE_W{1'b0}};
            load_index<={LOAD_W{1'b0}};
            local_index<={INDEX_W{1'b0}};
            pc<={PC_W{1'b0}};
            program_addr<={PC_W{1'b0}};
            pin_index<=3'd0;
            lut_addr<=6'd0;
            read_addr<={ADDR_W{1'b0}};
            for(j=0;j<N_CLASSES;j=j+1)
                class_counts[j]<={SCORE_W{1'b0}};
        end else begin
            case(state)
                S_LOAD: begin
                    if(input_valid) begin
                        if(load_index == N_INPUT-1) begin
                            load_index<={LOAD_W{1'b0}};
                            state<=S_READY;
                        end else load_index<=load_index+1'b1;
                    end
                end
                S_READY: begin
                    if(start) begin
                        stage<={STAGE_W{1'b0}};
                        local_index<={INDEX_W{1'b0}};
                        pc<={PC_W{1'b0}};
                        program_addr<={PC_W{1'b0}};
                        pin_index<=3'd0;
                        lut_addr<=6'd0;
                        for(j=0;j<N_CLASSES;j=j+1)
                            class_counts[j]<={SCORE_W{1'b0}};
                        state<=S_FETCH;
                    end
                end
                S_FETCH: begin
                    program_addr<=pc;
                    pin_index<=3'd0;
                    lut_addr<=6'd0;
                    state<=S_ROM_WAIT;
                end
                S_ROM_WAIT: begin
                    if(USE_SPLIT!=0) state<=S_TRUTH_WAIT;
                    else state<=S_PIN_ADDR;
                end
                S_TRUTH_WAIT: state<=S_PIN_ADDR;
                S_PIN_ADDR: begin
                    if(operand_addr == PAD_ADDR) begin
                        lut_addr[pin_index]<=1'b0;
                        if(pin_index==3'd5) state<=S_EXEC;
                        else pin_index<=pin_index+3'd1;
                    end else begin
                        read_addr<=operand_addr;
                        state<=S_MEM_WAIT;
                    end
                end
                S_MEM_WAIT: state<=S_SAMPLE;
                S_SAMPLE: begin
                    lut_addr[pin_index]<=source_bit;
                    if(pin_index==3'd5) state<=S_EXEC;
                    else begin
                        pin_index<=pin_index+3'd1;
                        state<=S_PIN_ADDR;
                    end
                end
                S_EXEC: begin
                    if(stage==LAST_STAGE && active_class[CLASS_W] && lut_value)
                        class_counts[active_class[CLASS_W-1:0]] <=
                            class_counts[active_class[CLASS_W-1:0]]+1'b1;
                    if(local_index == active_stage_length-1'b1) begin
                        local_index<={INDEX_W{1'b0}};
                        if(stage==LAST_STAGE) state<=S_DONE;
                        else begin
                            stage<=stage+1'b1;
                            pc<=pc+1'b1;
                            state<=S_FETCH;
                        end
                    end else begin
                        local_index<=local_index+1'b1;
                        pc<=pc+1'b1;
                        state<=S_FETCH;
                    end
                end
                S_DONE: state<=S_LOAD;
                default: state<=S_LOAD;
            endcase
        end
    end
endmodule
`default_nettype wire
